    selectedTab: KuiklyThreadTab,
    tabs: List<KuiklyThreadTab> = KuiklyThreadTab.entries,
    onSelect: (KuiklyThreadTab) -> Unit
) {
    SlockTopTabBar(
        items = tabs.map { it.toSlockTabSpec().toTopTabBarItem() },
        selectedKey = selectedTab.toString(),
