        if (!contentExtrasVisible || markdownTimelineSignature.isEmpty()) {
            return@LaunchedEffect
        }
        snapshotFlow {
            val visibleItems = listState.layoutInfo.visibleItemsInfo
            if (visibleItems.isEmpty()) {
                emptyThreadMarkdownVisiblePreparsePlan()
