                val startedAt = TimeSource.Monotonic.markNow()
                val result =
                    prepareSlockMarkdownFullRendererBodies(
                        bodies = visiblePreparsePlan.candidates.map { candidate -> candidate.body },
                        maxBodies = visiblePreparsePlan.candidates.size
