)

private class ThreadUserScrollGeneration(
    var value: Int = 0
)

private fun ThreadListViewport.threadFirstVisibleMessageAnchor(
    timelineSlice: ThreadTimelineSlice,
    userScrollGeneration: Int
): ThreadVisibleMessageAnchor? {
    val firstMessageListItemIndex = timelineSlice.firstMessageListItemIndex()
    val messageCount = timelineSlice.messages.size
    if (messageCount <= 0) return null
    val item =
        layoutInfo.visibleItemsInfo
            .firstOrNull { item ->
                item.index >= firstMessageListItemIndex &&
                    item.index < firstMessageListItemIndex + messageCount
            }
            ?: return null
    val message = timelineSlice.messages.getOrNull(item.index - firstMessageListItemIndex) ?: return null
    return ThreadVisibleMessageAnchor(
        messageId = message.id,
        offset = item.offset,
        userScrollGeneration = userScrollGeneration
    )
}

internal fun shouldRestoreThreadOlderPageAnchor(
    capturedUserScrollGeneration: Int,
    currentUserScrollGeneration: Int
): Boolean = capturedUserScrollGeneration == currentUserScrollGeneration

internal fun ThreadTimelineSlice.visibleThreadReadAnchor(
    visibleListItemIndexes: List<Int>,
): ThreadReadAnchor? {
    if (visibleListItemIndexes.isEmpty()) return null
    val firstMessageIndex = firstMessageListItemIndex()
    return visibleListItemIndexes
        .asSequence()
        .mapNotNull { listIndex -> messages.getOrNull(listIndex - firstMessageIndex) }
        .mapNotNull { message ->
            message.seq?.takeIf { seq -> seq > 0L }?.let { seq ->
                ThreadReadAnchor(seq = seq, messageId = message.id)
            }
        }
        .maxByOrNull { anchor -> anchor.seq }
}

private fun ThreadListViewport.isThreadOlderAutoLoadThreshold(
    boundaryIndex: Int,
    userScrollGeneration: Int,
    lastSettledUserScrollGeneration: Int
): Boolean {
    if (boundaryIndex < 0) return false
    val layoutInfo = layoutInfo
    if (layoutInfo.totalItemsCount <= boundaryIndex) return false
    val firstVisibleIndex = layoutInfo.visibleItemsInfo.firstOrNull()?.index ?: return false
    return shouldThreadAutoLoadOlderMessages(
        boundaryIndex = boundaryIndex,
        firstVisibleIndex = firstVisibleIndex,
        userScrollGeneration = userScrollGeneration,
        lastSettledUserScrollGeneration = lastSettledUserScrollGeneration
    )
}

internal fun shouldThreadAutoLoadOlderMessages(
    boundaryIndex: Int,
    firstVisibleIndex: Int,
    userScrollGeneration: Int,
    lastSettledUserScrollGeneration: Int = 0
): Boolean {
    if (boundaryIndex < 0 || firstVisibleIndex < 0) return false
    if (userScrollGeneration <= lastSettledUserScrollGeneration) return false
    return firstVisibleIndex <= boundaryIndex + ThreadOlderAutoLoadVisibleItemThreshold
}

private suspend fun ThreadListViewport.awaitThreadMessagesLayoutFrame(): Boolean {
    repeat(ThreadLayoutStabilityMaxFrames) {
        val layoutInfo = layoutInfo
        if (layoutInfo.totalItemsCount > 0 &&
            layoutInfo.visibleItemsInfo.isNotEmpty() &&
            layoutInfo.viewportEndOffset > layoutInfo.viewportStartOffset
        ) {
            return true
        }
        delay(ThreadLayoutStabilityFrameDelayMs)
    }
    return false
}

private fun ThreadListViewport.isThreadItemVisible(index: Int): Boolean {
    if (index < 0) return false
    return layoutInfo.visibleItemsInfo.any { it.index == index }
}

// task #567: the target's current offset inside the viewport, or null when it
// is not among the visible items (= fully drifted).
private fun ThreadListViewport.focusedAnchorTargetOffset(targetIndex: Int): Int? =
    layoutInfo.visibleItemsInfo.firstOrNull { it.index == targetIndex }?.offset

private fun ThreadListViewport.canScrollToThreadItem(index: Int): Boolean =
    index >= 0 && layoutInfo.totalItemsCount > index

private suspend fun ThreadListViewport.scrollLatestItemToRenderedBottom(
    latestItemIndex: Int,
    trailingPaddingSize: Int = 0,
    commandStillCurrent: () -> Boolean
): Boolean {
    if (latestItemIndex < 0) return false
    if (layoutInfo.totalItemsCount <= latestItemIndex) {
        return false
    }
    val latestItem = layoutInfo.visibleItemsInfo.firstOrNull { it.index == latestItemIndex }
    val viewportHeight = layoutInfo.viewportEndOffset - layoutInfo.viewportStartOffset
    val offset =
        latestItem
            ?.let {
                threadLatestItemBottomAnchorScrollOffset(
                    itemSize = it.size,
                    viewportHeight = viewportHeight,
                    visibleItemCount = layoutInfo.visibleItemsInfo.size,
                    totalItemCount = layoutInfo.totalItemsCount,
                    trailingPaddingSize = trailingPaddingSize
                )
            }
            ?: 0
    if (!commandStillCurrent()) return false
    scrollToItem(latestItemIndex, offset)
    return commandStillCurrent()
}

private suspend fun ThreadListViewport.scrollThreadItemToFocusedViewport(
    itemIndex: Int,
    commandStillCurrent: () -> Boolean
): Boolean {
    if (itemIndex < 0 || layoutInfo.totalItemsCount <= itemIndex) {
        return false
    }
    var didScroll = false
    repeat(ThreadFocusedMessageCenterAttempts) {
        if (!commandStillCurrent()) return false
        val item = layoutInfo.visibleItemsInfo.firstOrNull { it.index == itemIndex }
        if (item == null) {
            scrollToItem(itemIndex)
            if (!commandStillCurrent()) return false
            delay(ThreadLayoutStabilityFrameDelayMs)
            if (!commandStillCurrent()) return false
            return@repeat
        }
        val viewportHeight = layoutInfo.viewportEndOffset - layoutInfo.viewportStartOffset
        val offset =
            threadFocusedItemScrollOffset(
                itemSize = item.size,
                viewportHeight = viewportHeight
            )
        scrollToItem(itemIndex, offset)
        if (!commandStillCurrent()) return false
        didScroll = true
        delay(ThreadLayoutStabilityFrameDelayMs)
        if (!commandStillCurrent()) return false
    }
    return didScroll
}

private suspend fun ThreadListViewport.scrollThreadItemToRenderedBottom(
    itemIndex: Int,
    trailingPaddingSize: Int,
    commandStillCurrent: () -> Boolean
): Boolean {
    if (itemIndex < 0 || layoutInfo.totalItemsCount <= itemIndex) return false
    var didScroll = false
    repeat(ThreadFocusedMessageCenterAttempts) {
        if (!commandStillCurrent()) return false
        val item = layoutInfo.visibleItemsInfo.firstOrNull { it.index == itemIndex }
        if (item == null) {
            scrollToItem(itemIndex)
            if (!commandStillCurrent()) return false
            delay(ThreadLayoutStabilityFrameDelayMs)
            if (!commandStillCurrent()) return false
            return@repeat
        }
        val viewportHeight = layoutInfo.viewportEndOffset - layoutInfo.viewportStartOffset
        val offset =
            threadLatestItemBottomAnchorScrollOffset(
                itemSize = item.size,
                viewportHeight = viewportHeight,
                visibleItemCount = layoutInfo.visibleItemsInfo.size,
                totalItemCount = layoutInfo.totalItemsCount,
                trailingPaddingSize = trailingPaddingSize
            )
        scrollToItem(itemIndex, offset)
        if (!commandStillCurrent()) return false
        didScroll = true
        delay(ThreadLayoutStabilityFrameDelayMs)
        if (!commandStillCurrent()) return false
    }
    return didScroll
}

private fun ThreadListViewport.threadFocusedTailFit(
    targetItemIndex: Int,
    latestMessageItemIndex: Int,
    bottomPaddingItemIndex: Int,
    viewportHeightPx: Int,
    trailingPaddingPx: Int
): ThreadFocusedTailFit {
    val visibleItems = layoutInfo.visibleItemsInfo
    val target = visibleItems.firstOrNull { item -> item.index == targetItemIndex }
    val latestMessage = visibleItems.firstOrNull { item -> item.index == latestMessageItemIndex }
    return resolveThreadFocusedTailFit(
        targetItemIndex = targetItemIndex,
        latestMessageItemIndex = latestMessageItemIndex,
        bottomPaddingItemIndex = bottomPaddingItemIndex,
        targetOffsetPx = target?.offset,
        targetSizePx = target?.size,
        latestMessageOffsetPx = latestMessage?.offset,
        latestMessageSizePx = latestMessage?.size,
        viewportHeightPx = viewportHeightPx,
        trailingPaddingPx = trailingPaddingPx
    )
}

private fun ThreadListViewport.threadViewportGeometryDiagnostics(targetIndex: Int): String {
    val info = layoutInfo
    val visibleItems = info.visibleItemsInfo
    val first = visibleItems.firstOrNull()
    val last = visibleItems.lastOrNull()
    val target = visibleItems.firstOrNull { item -> item.index == targetIndex }
    return "viewport=${info.viewportStartOffset}..${info.viewportEndOffset} " +
        "first=${first?.index ?: -1}:${first?.offset ?: 0}+${first?.size ?: 0} " +
        "last=${last?.index ?: -1}:${last?.offset ?: 0}+${last?.size ?: 0} " +
        "target=${target?.index ?: -1}:${target?.offset ?: 0}+${target?.size ?: 0}"
}

private suspend fun ThreadListViewport.awaitThreadMessagesLayoutStability(
    latestItemIndex: Int
): Boolean {
    var previous: ThreadMessagesLayoutStabilitySnapshot? = null
    var stableFrames = 0
    repeat(ThreadLayoutStabilityMaxFrames) {
        val current = threadMessagesLayoutStabilitySnapshot(latestItemIndex)
        if (current.canAnchor && current == previous) {
            stableFrames += 1
            if (stableFrames >= ThreadLayoutStabilityRequiredFrames) {
                return true
            }
        } else {
            previous = current
            stableFrames = 0
        }
        delay(ThreadLayoutStabilityFrameDelayMs)
    }
    return false
}

private fun ThreadListViewport.threadMessagesLayoutStabilitySnapshot(
    latestItemIndex: Int
): ThreadMessagesLayoutStabilitySnapshot {
    val layoutInfo = layoutInfo
    val visibleItems = layoutInfo.visibleItemsInfo
    val first = visibleItems.firstOrNull()
    val last = visibleItems.lastOrNull()
    val latest = visibleItems.firstOrNull { it.index == latestItemIndex }
    return ThreadMessagesLayoutStabilitySnapshot(
        totalItemCount = layoutInfo.totalItemsCount,
        viewportStartOffset = layoutInfo.viewportStartOffset,
        viewportEndOffset = layoutInfo.viewportEndOffset,
        visibleItemCount = visibleItems.size,
        firstItemIndex = first?.index ?: -1,
        firstItemOffset = first?.offset ?: 0,
        firstItemSize = first?.size ?: 0,
        lastItemIndex = last?.index ?: -1,
        lastItemOffset = last?.offset ?: 0,
        lastItemSize = last?.size ?: 0,
        latestItemIndex = latest?.index ?: -1,
        latestItemOffset = latest?.offset ?: 0,
        latestItemSize = latest?.size ?: 0,
        canAnchor = latestItemIndex >= 0 &&
            layoutInfo.totalItemsCount > latestItemIndex &&
            visibleItems.isNotEmpty() &&
            layoutInfo.viewportEndOffset > layoutInfo.viewportStartOffset
    )
}

private data class ThreadMessagesLayoutStabilitySnapshot(
    val totalItemCount: Int,
    val viewportStartOffset: Int,
    val viewportEndOffset: Int,
    val visibleItemCount: Int,
    val firstItemIndex: Int,
    val firstItemOffset: Int,
    val firstItemSize: Int,
    val lastItemIndex: Int,
    val lastItemOffset: Int,
    val lastItemSize: Int,
    val latestItemIndex: Int,
    val latestItemOffset: Int,
    val latestItemSize: Int,
    val canAnchor: Boolean
)

internal fun threadLatestItemBottomAnchorScrollOffset(
    itemSize: Int,
    viewportHeight: Int,
    visibleItemCount: Int,
    totalItemCount: Int,
    trailingPaddingSize: Int = 0
): Int {
    if (itemSize <= 0 || viewportHeight <= 0) return 0
    return itemSize + trailingPaddingSize.coerceAtLeast(0) - viewportHeight
}

internal fun threadInitialBottomAnchorScrollDelta(
    itemOffset: Int,
    itemSize: Int,
    trailingPaddingSize: Int,
    viewportEndOffset: Int
): Int =
    itemOffset +
        itemSize.coerceAtLeast(0) +
        trailingPaddingSize.coerceAtLeast(0) -
        viewportEndOffset

internal fun threadFocusedItemScrollOffset(
    itemSize: Int,
    viewportHeight: Int
): Int {
    return 0
}

private fun ThreadListViewport.shouldShowThreadBackToBottom(latestItemIndex: Int): Boolean {
    if (latestItemIndex <= 0) return false
    if (!canScrollForward) return false
    val layoutInfo = layoutInfo
    if (layoutInfo.totalItemsCount <= latestItemIndex) return false
    val latestItem = layoutInfo.visibleItemsInfo.firstOrNull { it.index == latestItemIndex }
    val latestBottom = latestItem?.let { it.offset + it.size } ?: return true
    return latestBottom < layoutInfo.viewportEndOffset - ThreadBackToBottomTolerancePx
}

private fun ThreadListViewport.isLatestItemAtRenderedBottom(
    latestItemIndex: Int,
    trailingPaddingSize: Int = 0
): Boolean {
    val layoutInfo = layoutInfo
    if (layoutInfo.totalItemsCount <= latestItemIndex) return false
    val latestItem = layoutInfo.visibleItemsInfo.firstOrNull { it.index == latestItemIndex } ?: return false
    val latestBottom = latestItem.offset + latestItem.size + trailingPaddingSize.coerceAtLeast(0)
    return kotlin.math.abs(latestBottom - layoutInfo.viewportEndOffset) <= ThreadBackToBottomTolerancePx
}

@Composable
private fun ThreadBackToBottomButton(
    modifier: Modifier = Modifier,
    onClick: () -> Unit
) {
    // Kuikly latches native-dispatch capture from the pointer's ACTION_DOWN
    // hit path. A same-bounds sibling behind this button is not part of that
    // path, so it cannot reliably prevent the native host from also starting
    // a gesture on the message row underneath. Put the capture marker on the
    // interactive button's own ancestor path; Compose still delivers the
    // gesture to SlockAnchorButton, while Android's native dispatch stays
    // captured for the complete DOWN..UP sequence.
    SlockBrutalActionButton(
        label = stringResource(MR.strings.thread_action_back_to_bottom),
        onClick = onClick,
        modifier = modifier.slockNativeDispatchCapture(),
        backgroundColor = SlockColor.SurfaceWhite,
        minWidth = 0.dp,
        minHeight = ThreadFloatingPillButtonMinHeight,
        shadowOffset = 4.dp,
        textStyle = SlockType.Caption.withSlockFontWeight(FontWeight.Bold).copy(color = SlockColor.TextBlack),
        trailingContent = {
            SlockLucideIcon(
                "chevron-down",
                modifier = Modifier.size(14.dp),
                color = "#FF000000"
            )
        }
    )
}

@Composable
private fun ThreadUnreadJumpButton(
    unreadCount: Int,
    modifier: Modifier = Modifier,
    onClick: () -> Unit,
) {
    SlockBrutalActionButton(
        label = stringResource(MR.strings.thread_action_unread_count, unreadCount),
        onClick = onClick,
        modifier = modifier.slockNativeDispatchCapture(),
        // artin visual ruling (task #232): neutral white pill, bottom placement.
        backgroundColor = SlockColor.SurfaceWhite,
        minWidth = 0.dp,
        minHeight = ThreadFloatingPillButtonMinHeight,
        shadowOffset = 4.dp,
        textStyle = SlockType.Caption.withSlockFontWeight(FontWeight.Bold).copy(color = SlockColor.TextBlack),
    )
}

internal fun shouldShowThreadUnreadJumpButton(
    preferenceEnabled: Boolean,
    routeActive: Boolean,
    hostForeground: Boolean,
    unreadCount: Int,
    targetMessageId: String?,
    inlineSearchVisible: Boolean,
    atCanonicalBottom: Boolean = false,
): Boolean =
    preferenceEnabled &&
        routeActive &&
        hostForeground &&
        unreadCount > 0 &&
        !targetMessageId.isNullOrBlank() &&
        !inlineSearchVisible &&
        !atCanonicalBottom

internal fun threadUnreadJumpAtCanonicalBottom(
    canLoadMoreAfter: Boolean,
    canScrollTowardBottom: Boolean,
    latestItemOffBottom: Boolean,
): Boolean = !canLoadMoreAfter && !canScrollTowardBottom && !latestItemOffBottom

internal fun threadVisibleReadTailMessageIndex(
    visibleListItemIndexes: List<Int>,
    firstMessageListItemIndex: Int,
    messageCount: Int,
): Int? {
    if (messageCount <= 0) return null
    val lastMessageListItemIndex = firstMessageListItemIndex + messageCount - 1
    return visibleListItemIndexes
        .asSequence()
        .filter { index -> index in firstMessageListItemIndex..lastMessageListItemIndex }
        .maxOrNull()
        ?.minus(firstMessageListItemIndex)
}

internal fun consumeUnreadJumpFrontierAtCanonicalBottom(
    sessionAnchor: ThreadReadAnchor?,
    latestCanonicalMessage: ThreadReadAnchor?,
    atCanonicalBottom: Boolean,
): ThreadReadAnchor? =
    if (atCanonicalBottom) {
        advanceThreadReadAnchorFrontier(sessionAnchor, latestCanonicalMessage)
    } else {
        sessionAnchor
    }

private const val ThreadBackToBottomReleaseGuardMillis = 64L
private const val ThreadUnreadJumpButtonZIndex = 5f

/**
 * Compact floating thread pills (back-to-bottom and unread-jump).
 * artin 2026-09-02: nothing in this family needs the 42.dp action-button target.
 */
internal val ThreadFloatingPillButtonMinHeight = 28.dp
private const val ThreadBackToBottomTolerancePx = 24
private const val ThreadBottomAnchorMinimumAttempts = 2
private const val ThreadInitialBottomAnchorAttempts = 12
private const val ThreadInitialBottomAnchorRetryDelayMs = 80L
private const val ThreadFocusedTailMeasurementRetryFrames = 2
private const val ThreadViewportPixelProbeTimeoutMs = 2_500L
private const val ThreadInitialBottomAnchorMinimumConsumedDeltaPx = 0.5f
private const val ThreadLayoutStabilityFrameDelayMs = 16L
private const val ThreadFirstContentTaskJoinDelayMs = 96L
private const val ThreadLayoutStabilityMaxFrames = 30
private const val ThreadLayoutStabilityRequiredFrames = 3
private const val ThreadBackToBottomAnchorAttempts = 12
private const val ThreadKeyboardBottomAnchorAttempts = 8
private const val ThreadOlderAutoLoadVisibleItemThreshold = 8
private const val ThreadShareCaptureTopScrollOffsetPx = -12
private const val ThreadShareCaptureScrollSettleMs = 96L
private const val ThreadShareCaptureMaxSegmentsPerMessage = 24
private const val ThreadShareCaptureGeometryTolerancePx = 2f
private val ThreadSystemMessageTimeColor = SlockColor.TextBlack.copy(alpha = 0.4f)
private val ThreadSystemMessageBodyColor = SlockColor.TextBlack.copy(alpha = 0.5f)

@Composable
private fun ThreadSystemMessageRow(
    message: KuiklyThreadMessageItem,
    timestampValue: String
) {
    var expanded by remember(message.id) { mutableStateOf(false) }
    val timestampLayout = remember { threadSystemMessageTimestampLayoutSpec() }
    val systemBody =
        remember(message.body, message.metadata, message.systemEventType, expanded) {
            if (expanded) {
                message.expandedSystemContent()
            } else {
                message.systemContentSummary()
            }
        }
    Row(
        modifier =
            Modifier.fillMaxWidth()
                .background(SlockColor.SurfaceWhite)
                .clickable { expanded = !expanded }
                .padding(horizontal = SlockSpacing.Md, vertical = SlockSpacing.Xs),
        horizontalArrangement = Arrangement.spacedBy(SlockSpacing.Sm, Alignment.CenterHorizontally),
        verticalAlignment = Alignment.Top
    ) {
        SlockRelativeTimestampText(
            value = timestampValue,
            displayGroup = SlockTimestampDisplayGroup.Conversation,
            style = SlockType.Caption.copy(color = ThreadSystemMessageTimeColor, fontFamily = SlockMonoFamily),
            color = ThreadSystemMessageTimeColor,
            textAlign = TextAlign.End,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
            modifier =
                if (timestampLayout.reserveFullMetadataGutter) {
                    Modifier.width(timestampLayout.maxWidthDp.dp)
                } else {
                    Modifier.widthIn(max = timestampLayout.maxWidthDp.dp).wrapContentWidth()
                }
        )
        Text(
            text = systemBody,
            style = SlockType.Caption.copy(color = ThreadSystemMessageBodyColor),
            color = ThreadSystemMessageBodyColor,
            textAlign = TextAlign.Center,
            maxLines = if (expanded) Int.MAX_VALUE else 1,
            overflow = if (expanded) TextOverflow.Clip else TextOverflow.Ellipsis,
            // Let short timestamp/body groups stay centered; long bodies still use the remaining width.
            modifier = Modifier.weight(1f, fill = false)
        )
    }
}

@Composable
private fun ThreadNewerMessagesBoundaryRow(
    newerMessagesStatus: String,
    onRetry: () -> Unit
) {
    val spec = threadNewerMessagesActionSpec(newerMessagesStatus)
    if (spec.event == "retryLoadNewer") {
        ThreadInlineActionRow(
            label = spec.label.localized(),
            leadingIcon = spec.leadingIcon,
            onClick = onRetry
        )
        return
    }
    Box(
        modifier = Modifier.fillMaxWidth().height(ThreadNewerMessagesBoundaryHeight),
        contentAlignment = Alignment.Center
    ) {
        if (newerMessagesStatus == "loading") {
            Text(
                text = spec.label.localized(),
                style = SlockType.Caption.copy(color = SlockColor.TextMutedGray),
                color = SlockColor.TextMutedGray
            )
        }
    }
}

@Composable
private fun ThreadInlineActionRow(
    label: String,
    leadingIcon: SlockLucideIconName? = null,
    onClick: () -> Unit
) {
    SlockBrutalActionButton(
        label = label,
        onClick = onClick,
        modifier = Modifier.fillMaxWidth(),
        backgroundColor = SlockColor.SurfaceWhite,
        minWidth = 0.dp,
        minHeight = 36.dp,
        leadingIcon = leadingIcon,
        shadowOffset = 2.dp,
        textStyle = SlockType.ButtonBold.copy(fontSize = 12.sp, color = SlockColor.TextBlack)
    )
}

@Composable
private fun ThreadHistoryStatusRow(
    spec: ThreadHistoryStatusSpec
) {
    Column(
        modifier = Modifier.fillMaxWidth().padding(horizontal = SlockSpacing.Md, vertical = 8.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Row(
            horizontalArrangement = Arrangement.Center,
            verticalAlignment = Alignment.CenterVertically
        ) {
            spec.leadingIcon?.let { iconName ->
                SlockLucideIcon(
                    iconName,
                    modifier = Modifier.size(14.dp),
                    color = "#FF6B7280"
                )
