private fun Modifier.threadMessageContentWidth(maxWidthFraction: Float): Modifier =
    if (maxWidthFraction < 1f) {
        fillMaxWidth(maxWidthFraction)
    } else {
        fillMaxWidth()
    }

// Mobile press feedback (task #555): the finger-down point washes gray and a
// ripple spreads across the row — replacing the web-style press border. The
// indication is delayed past touch-slop so a scroll that starts on a message
// never flashes it: a drag steals the pointer and cancels the press scope
// before the delay elapses.
private const val ThreadMessagePressIndicationDelayMs = 120L
private const val ThreadMessageRippleExpandMs = 260
private const val ThreadMessageRippleFadeMs = 240
private const val ThreadMessageRippleResetMarginMs = 60L
private const val ThreadMessageRippleAlpha = 0.10f
private val ThreadMessageRippleMinRadius = 24.dp

internal fun threadMessageUsesFullRowLongPressActions(shareSelectionActive: Boolean): Boolean =
    !shareSelectionActive

internal data class ThreadMessageLongPressDispatchDecision(
    val allowed: Boolean,
    val reason: String,
    val scrollInProgress: Boolean
)

internal fun decideThreadMessageLongPressDispatch(
    detectorAccepted: Boolean,
    directPointerMovementDetected: Boolean,
    isScrollInProgress: Boolean
): ThreadMessageLongPressDispatchDecision =
    // LazyListState reports both direct drags and programmatic anchor/focus movement as scrolling.
    // The gesture detector owns direct-drag cancellation; list motion is diagnostic context only.
    ThreadMessageLongPressDispatchDecision(
        allowed = detectorAccepted && !directPointerMovementDetected,
        reason =
            when {
                !detectorAccepted -> "detector_not_admitted"
                directPointerMovementDetected -> "direct_pointer_movement"
                else -> "admitted"
            },
        scrollInProgress = isScrollInProgress
    )

internal fun threadMessageTapOpensThread(
    showReplyAction: Boolean,
    replyCount: Int,
    shareSelectionActive: Boolean,
    hasLocalSendState: Boolean,
    singleTapOpensThreadEnabled: Boolean
): Boolean =
    singleTapOpensThreadEnabled &&
        replyCount > 0 &&
        threadMessageBodyTapEligible(showReplyAction, shareSelectionActive, hasLocalSendState)

internal fun threadMessageBodyTapEligible(
    showReplyAction: Boolean,
    shareSelectionActive: Boolean,
    hasLocalSendState: Boolean
): Boolean =
    showReplyAction && !shareSelectionActive && !hasLocalSendState

internal fun threadMessageOpenIgnoredForSurface(surfaceKind: String): Boolean =
    surfaceKind == KuiklyThreadSurfaceKind.ReplyThread

@Composable
private fun BoxScope.ThreadMessagePressRipple(
    pressed: Boolean,
    origin: Offset?
) {
    val expansion by animateFloatAsState(
        targetValue = if (origin != null) 1f else 0f,
        animationSpec = tween(durationMillis = if (origin != null) ThreadMessageRippleExpandMs else 0),
        label = "thread-message-ripple-expansion"
    )
    val washAlpha by animateFloatAsState(
        targetValue = if (pressed && origin != null) ThreadMessageRippleAlpha else 0f,
        animationSpec =
            tween(durationMillis = if (pressed) ThreadMessageRippleExpandMs else ThreadMessageRippleFadeMs),
        label = "thread-message-ripple-alpha"
    )
    if (!shouldDrawThreadMessagePressRipple(origin != null, washAlpha, expansion)) return
    val rippleOrigin = origin ?: return
    Canvas(modifier = Modifier.matchParentSize()) {
        val coverRadius = hypot(size.width, size.height)
        val minRadius = ThreadMessageRippleMinRadius.toPx()
        val radius = threadMessageRippleRadius(minRadius, coverRadius, expansion)
        drawCircle(
            color = Color.Black.copy(alpha = washAlpha),
            radius = radius,
            center = rippleOrigin
        )
    }
}

internal fun shouldDrawThreadMessagePressRipple(
    hasOrigin: Boolean,
    washAlpha: Float,
    expansion: Float
): Boolean = hasOrigin && washAlpha > 0f && expansion > 0f

internal fun threadMessageRippleRadius(
    minRadius: Float,
    coverRadius: Float,
    expansion: Float
): Float = minRadius + (coverRadius - minRadius) * expansion

internal fun Modifier.threadMessagePointerInput(
    role: String,
    messageId: String,
    pointerSessionKey: Int,
    gestureOwner: ThreadMessageLongPressGestureOwner,
    block: suspend PointerInputScope.() -> Unit
): Modifier = pointerInput(role, messageId, pointerSessionKey, gestureOwner, block = block)

@Composable
internal fun rememberThreadMessageLongPressGestureOwner(
    instanceKey: Any,
    messageId: String
): ThreadMessageLongPressGestureOwner {
    val ownerStore = LocalThreadMessageLongPressGestureOwnerStore.current
    val fallbackTapDispatchScope = rememberCoroutineScope()
    val fallbackOwnerStore = remember(fallbackTapDispatchScope) {
        ThreadMessageLongPressGestureOwnerStore(tapDispatchScope = fallbackTapDispatchScope)
    }
    val effectiveOwnerStore = ownerStore ?: fallbackOwnerStore
    val ownerKey =
        remember(instanceKey, messageId) {
            ThreadMessageLongPressGestureOwnerKey(instanceKey, messageId)
        }
    val gestureOwner =
        remember(effectiveOwnerStore, ownerKey) {
            effectiveOwnerStore.ownerFor(ownerKey)
        }
    DisposableEffect(effectiveOwnerStore, ownerKey, gestureOwner) {
        effectiveOwnerStore.retain(ownerKey, gestureOwner)
        onDispose {
            effectiveOwnerStore.release(ownerKey, gestureOwner)
        }
    }
    return gestureOwner
}

@Composable
internal fun Modifier.threadMessageLongPressActions(
    messageId: String,
    pointerSessionKey: Int,
    gestureOwner: ThreadMessageLongPressGestureOwner,
    isScrollInProgress: () -> Boolean = { false },
    diagnosticsLogger: (String) -> Unit = {},
    onTap: (() -> Unit)? = null,
    onTapRejected: (ThreadMessageTapMovementDecision) -> Unit = {},
    onShowActions: (SlockPopoverAnchor) -> Unit,
    onInputReady: ((String) -> Unit)? = null
): Modifier {
    SideEffect {
        gestureOwner.updateCallbacks(
            ThreadMessageLongPressCallbacks(
                isScrollInProgress = isScrollInProgress,
                diagnosticsLogger = diagnosticsLogger,
                onTap = onTap,
                onTapRejected = onTapRejected,
                onShowActions = onShowActions,
                onInputReady = onInputReady
            )
        )
    }
    gestureOwner.tapMovementGate.activatePointerSession(pointerSessionKey)
    return this
        .slockCaptureLiveRootAnchor(gestureOwner.rootAnchor)
        .threadMessagePointerInput(
            role = "tap_movement",
            messageId = messageId,
            pointerSessionKey = pointerSessionKey,
            gestureOwner = gestureOwner
        ) {
            awaitEachGesture {
                val down = awaitFirstDown(requireUnconsumed = false)
                val compositionLease =
                    gestureOwner.captureActiveLease() ?: return@awaitEachGesture
                gestureOwner.tapMovementGate.begin(down.position, compositionLease)
                do {
                    val event = awaitPointerEvent()
                    val activeChange = event.changes.firstOrNull { it.id == down.id }
                    if (gestureOwner.isLeaseActive(compositionLease)) {
                        gestureOwner.tapMovementGate.observe(
                            position = activeChange?.position,
                            pointerCount = event.changes.size,
                            touchSlop = viewConfiguration.touchSlop
                        )
                    }
                } while (event.changes.any { it.pressed })
            }
        }
        .threadMessagePointerInput(
            role = "actions",
            messageId = messageId,
            pointerSessionKey = pointerSessionKey,
            gestureOwner = gestureOwner
        ) {
            detectTapGestures(
                onPress = { downPosition ->
                    val compositionLease =
                        gestureOwner.captureActiveLease() ?: return@detectTapGestures
                    // The visual harness uses this optional seam to prove that the exact target
                    // row received the real ACTION_DOWN. The callback lives on the route-owned
                    // gesture owner, so a replacement composition updates the existing handler.
                    gestureOwner.callbacksSnapshot(compositionLease)?.onInputReady?.invoke(messageId)
                    var indicated = false
                    try {
                        // Scrolls steal the pointer and cancel this scope
                        // within the delay — press feedback never shows for
                        // them (task #555).
                        delay(ThreadMessagePressIndicationDelayMs)
                        indicated = gestureOwner.showPressFeedback(compositionLease, downPosition)
                        tryAwaitRelease()
                    } finally {
                        if (indicated) {
                            gestureOwner.hidePressFeedback(compositionLease)
                        }
                    }
                },
                onTap = {
                    val gestureToken = gestureOwner.tapMovementGate.currentGestureToken()
                    val compositionLease =
                        gestureOwner.captureActiveLease(gestureToken.compositionGeneration)
                            ?: return@detectTapGestures
                    gestureOwner.tapDispatchScope.launch {
                        // Native rich-text annotations may dispatch their Clickable callback
                        // after the parent pointer detector completes. Commit on the next frame
                        // so every child callback from this gesture can reject its generation.
                        withFrameNanos { }
                        val callbacks =
                            gestureOwner.callbacksSnapshot(compositionLease) ?: return@launch
                        val decision = gestureOwner.tapMovementGate.decision(gestureToken)
                        if (decision.allowed) {
                            callbacks.onTap?.invoke()
                        } else if (callbacks.onTap != null) {
                            callbacks.onTapRejected(decision)
                        }
                    }
                },
                onLongPress = { localOffset ->
                    val gestureToken = gestureOwner.tapMovementGate.currentGestureToken()
                    val compositionLease =
                        gestureOwner.captureActiveLease(gestureToken.compositionGeneration)
                            ?: run {
                                diagnosticsLogger(
                                    "thread_message_long_press_no_lease messageId=$messageId"
                                )
                                return@detectTapGestures
                            }
                    val callbacks =
                        gestureOwner.callbacksSnapshot(compositionLease)
                            ?: run {
                                diagnosticsLogger(
                                    "thread_message_long_press_no_callbacks messageId=$messageId"
                                )
                                return@detectTapGestures
                            }
                    val movementDecision = gestureOwner.tapMovementGate.decision(gestureToken)
                    val directPointerMovementDetected =
                        movementDecision.reason == "movement" || movementDecision.reason == "multi_touch"
                    val dispatchDecision =
                        decideThreadMessageLongPressDispatch(
                            detectorAccepted = movementDecision.allowed,
                            directPointerMovementDetected = directPointerMovementDetected,
                            isScrollInProgress = callbacks.isScrollInProgress()
                        )
                    if (!dispatchDecision.allowed) {
                        callbacks.diagnosticsLogger(
                            "thread_message_long_press_rejected messageId=$messageId " +
                                "reason=${dispatchDecision.reason} movement=${movementDecision.maxDistance} " +
                                "touchSlop=${movementDecision.touchSlop} pointers=${movementDecision.pointerCount}"
                        )
                        return@detectTapGestures
                    }
                    callbacks.diagnosticsLogger(
                        "thread_message_long_press_admitted messageId=$messageId " +
                            "scrollInProgress=${dispatchDecision.scrollInProgress}"
                    )
                    val anchor =
                        gestureOwner.rootAnchor.resolve(SlockPopoverLocalPoint.Exact(localOffset))
                    if (anchor == null) {
                        callbacks.diagnosticsLogger(
                            "thread_message_long_press_anchor_unavailable messageId=$messageId " +
                                "scrollInProgress=${dispatchDecision.scrollInProgress}"
                        )
                        return@detectTapGestures
                    }
                    callbacks.diagnosticsLogger(
                        "thread_message_long_press_menu_emit messageId=$messageId " +
                            "scrollInProgress=${dispatchDecision.scrollInProgress}"
                    )
                    callbacks.onShowActions(anchor)
                }
            )
        }
}

internal data class ThreadMessageTapMovementDecision(
    val allowed: Boolean,
    val reason: String,
    val maxDistance: Float,
    val touchSlop: Float,
    val pointerCount: Int
)

internal data class ThreadMessageTapGestureToken(
    val pointerSessionKey: Int,
    val gestureGeneration: Int,
    val compositionGeneration: Long
)

internal val LocalThreadMessagePointerSessionKey = compositionLocalOf { 0 }

internal data class ThreadMessageLongPressGestureOwnerKey(
    val instanceKey: Any,
    val messageId: String
)

internal data class ThreadMessageLongPressCompositionLease(
    val generation: Long
)

internal data class ThreadMessageLongPressCallbacks(
    val isScrollInProgress: () -> Boolean = { false },
    val diagnosticsLogger: (String) -> Unit = {},
    val onTap: (() -> Unit)? = null,
    val onTapRejected: (ThreadMessageTapMovementDecision) -> Unit = {},
    val onShowActions: (SlockPopoverAnchor) -> Unit = {},
    val onInputReady: ((String) -> Unit)? = null
)

internal class ThreadMessageLongPressGestureOwner(
    val key: ThreadMessageLongPressGestureOwnerKey,
    val tapDispatchScope: CoroutineScope
) {
    val rootAnchor =
        SlockLiveRootAnchorRef(identity = threadMessageMenuOwnerIdentity(key.messageId))
    val tapMovementGate = ThreadMessageTapMovementGate()

    var pressed by mutableStateOf(false)
        private set
    var pressRippleOrigin by mutableStateOf<Offset?>(null)
        private set

    private var callbacks = ThreadMessageLongPressCallbacks()
    private var compositionGeneration = 0L
    private var compositionActive = false

    internal fun retainCompositionAuthority() {
        if (compositionActive) return
        compositionGeneration = nextThreadMessageCompositionGeneration(compositionGeneration)
        compositionActive = true
    }

    internal fun finalizeInactiveCompositionAuthority() {
        if (!compositionActive) return
        compositionActive = false
        callbacks = ThreadMessageLongPressCallbacks()
        tapMovementGate.invalidateCompositionAuthority()
        rootAnchor.invalidate()
        pressed = false
        pressRippleOrigin = null
    }

    fun captureActiveLease(): ThreadMessageLongPressCompositionLease? =
        if (compositionActive) {
            ThreadMessageLongPressCompositionLease(compositionGeneration)
        } else {
            null
        }

    fun captureActiveLease(
        expectedGeneration: Long
    ): ThreadMessageLongPressCompositionLease? =
        captureActiveLease()?.takeIf { it.generation == expectedGeneration }

    fun isLeaseActive(lease: ThreadMessageLongPressCompositionLease): Boolean =
        compositionActive && lease.generation == compositionGeneration

    fun updateCallbacks(next: ThreadMessageLongPressCallbacks) {
        if (compositionActive) callbacks = next
    }

    fun callbacksSnapshot(
        lease: ThreadMessageLongPressCompositionLease
    ): ThreadMessageLongPressCallbacks? = callbacks.takeIf { isLeaseActive(lease) }

    fun showPressFeedback(
        lease: ThreadMessageLongPressCompositionLease,
        origin: Offset
    ): Boolean {
        if (!isLeaseActive(lease)) return false
        pressRippleOrigin = origin
        pressed = true
        return true
    }

    fun hidePressFeedback(lease: ThreadMessageLongPressCompositionLease) {
        if (isLeaseActive(lease)) pressed = false
    }

    fun clearReleasedPressRipple(
        lease: ThreadMessageLongPressCompositionLease,
        expectedOrigin: Offset
    ) {
        if (isLeaseActive(lease) && !pressed && pressRippleOrigin == expectedOrigin) {
            pressRippleOrigin = null
        }
    }
}

internal fun nextThreadMessageCompositionGeneration(current: Long): Long =
    if (current == Long.MAX_VALUE) 0L else current + 1L

internal const val ThreadMessageLongPressGestureOwnerRetentionLimit = 256

internal class ThreadMessageLongPressGestureOwnerStore(
    private val tapDispatchScope: CoroutineScope,
    private val maxRetainedOwners: Int = ThreadMessageLongPressGestureOwnerRetentionLimit
) {
    init {
        require(maxRetainedOwners > 0) { "maxRetainedOwners must be positive" }
    }

    private data class Entry(
        val owner: ThreadMessageLongPressGestureOwner,
        var activeOwnerCount: Int,
        var lastAccessOrdinal: Long,
        var lifecycleRevision: Long
    )

    private val owners = mutableMapOf<ThreadMessageLongPressGestureOwnerKey, Entry>()
    private var accessOrdinal = 0L

    fun ownerFor(instanceKey: Any, messageId: String): ThreadMessageLongPressGestureOwner =
        ownerFor(ThreadMessageLongPressGestureOwnerKey(instanceKey, messageId))

    fun ownerFor(key: ThreadMessageLongPressGestureOwnerKey): ThreadMessageLongPressGestureOwner {
        owners[key]?.let { entry ->
            entry.lastAccessOrdinal = nextAccessOrdinal()
            return entry.owner
        }
        return ThreadMessageLongPressGestureOwner(key, tapDispatchScope)
            .also { owner ->
                owners[key] =
                    Entry(
                        owner = owner,
                        activeOwnerCount = 0,
                        lastAccessOrdinal = nextAccessOrdinal(),
                        lifecycleRevision = 0L
                    )
            }
    }

    fun retain(
        key: ThreadMessageLongPressGestureOwnerKey,
        owner: ThreadMessageLongPressGestureOwner
    ) {
        val entry = owners[key]
        if (entry == null || entry.owner !== owner) {
            entry?.owner?.finalizeInactiveCompositionAuthority()
            owner.retainCompositionAuthority()
            owners[key] =
                Entry(
                    owner = owner,
                    activeOwnerCount = 1,
                    lastAccessOrdinal = nextAccessOrdinal(),
                    lifecycleRevision = 1L
                )
        } else {
            entry.lifecycleRevision = nextThreadMessageCompositionGeneration(entry.lifecycleRevision)
            if (entry.activeOwnerCount == 0) owner.retainCompositionAuthority()
            entry.activeOwnerCount += 1
            entry.lastAccessOrdinal = nextAccessOrdinal()
        }
        pruneInactiveOwners()
    }

    fun release(
        key: ThreadMessageLongPressGestureOwnerKey,
        owner: ThreadMessageLongPressGestureOwner
    ) {
        val entry = owners[key]?.takeIf { it.owner === owner } ?: return
        if (entry.activeOwnerCount > 0) entry.activeOwnerCount -= 1
        if (entry.activeOwnerCount != 0) return
        entry.lifecycleRevision = nextThreadMessageCompositionGeneration(entry.lifecycleRevision)
        val expectedLifecycleRevision = entry.lifecycleRevision
        tapDispatchScope.launch(start = CoroutineStart.UNDISPATCHED) {
            // DisposableEffect replacement can apply as 1→0→1. Yield beyond the current apply
            // stack so a same-semantic retain can reclaim the continuing gesture authority.
            yield()
            val currentEntry = owners[key]
            if (
                currentEntry?.owner === owner &&
                    currentEntry.activeOwnerCount == 0 &&
                    currentEntry.lifecycleRevision == expectedLifecycleRevision
            ) {
                owner.finalizeInactiveCompositionAuthority()
                pruneInactiveOwners()
            }
        }
    }

    private fun pruneInactiveOwners() {
        while (owners.size > maxRetainedOwners) {
            val oldestInactive =
                owners.entries
                    .filter { (_, entry) ->
                        entry.activeOwnerCount == 0 && entry.owner.captureActiveLease() == null
                    }
                    .minByOrNull { (_, entry) -> entry.lastAccessOrdinal }
                    ?: return
            owners.remove(oldestInactive.key)?.owner?.finalizeInactiveCompositionAuthority()
        }
    }

    private fun nextAccessOrdinal(): Long {
        accessOrdinal += 1L
        return accessOrdinal
    }
}

internal val LocalThreadMessageLongPressGestureOwnerStore =
    compositionLocalOf<ThreadMessageLongPressGestureOwnerStore?> { null }

internal fun nextThreadPointerSessionKey(current: Int): Int =
    if (current == Int.MAX_VALUE) 0 else current + 1

internal class ThreadMessageTapMovementGate {
    private var downPosition: Offset? = null
    private var canceled: Boolean = false
    private var reason: String = "none"
    private var maxDistance: Float = 0f
    private var touchSlop: Float = 0f
    private var pointerCount: Int = 1
    private var gestureGeneration: Int = 0
    private var pointerSessionKey: Int = 0
    private var compositionGeneration: Long = 0L

    fun activatePointerSession(pointerSessionKey: Int) {
        if (this.pointerSessionKey == pointerSessionKey) return
        this.pointerSessionKey = pointerSessionKey
        downPosition = null
        canceled = true
        reason = "session_superseded"
    }

    fun begin(
        position: Offset,
        compositionLease: ThreadMessageLongPressCompositionLease =
            ThreadMessageLongPressCompositionLease(generation = 0L)
    ) {
        gestureGeneration = nextThreadPointerSessionKey(gestureGeneration)
        compositionGeneration = compositionLease.generation
        downPosition = position
        canceled = false
        reason = "none"
        maxDistance = 0f
        touchSlop = 0f
        pointerCount = 1
    }

    fun observe(
        position: Offset?,
        pointerCount: Int,
        touchSlop: Float
    ) {
        this.touchSlop = touchSlop
        this.pointerCount = pointerCount
        val down = downPosition
        if (down == null || position == null) {
            canceled = true
            reason = "missing_pointer"
            return
        }
        if (pointerCount != 1) {
            canceled = true
            reason = "multi_touch"
            return
        }
        maxDistance = maxOf(maxDistance, (position - down).getDistance())
        if (maxDistance > touchSlop) {
            canceled = true
            reason = "movement"
        }
    }

    fun rejectChildAction(source: String) {
        if (downPosition == null) return
        canceled = true
        reason = "child_action:$source"
    }

    fun currentGestureToken(): ThreadMessageTapGestureToken =
        ThreadMessageTapGestureToken(
            pointerSessionKey = pointerSessionKey,
            gestureGeneration = gestureGeneration,
            compositionGeneration = compositionGeneration
        )

    fun invalidateCompositionAuthority() {
        gestureGeneration = nextThreadPointerSessionKey(gestureGeneration)
        downPosition = null
        canceled = true
        reason = "composition_inactive"
    }

    fun decision(
        expectedGestureToken: ThreadMessageTapGestureToken = currentGestureToken()
    ): ThreadMessageTapMovementDecision =
        ThreadMessageTapMovementDecision(
            allowed =
                expectedGestureToken.pointerSessionKey == pointerSessionKey &&
                    expectedGestureToken.gestureGeneration == gestureGeneration &&
                    downPosition != null &&
                    !canceled,
            reason =
                when {
                    expectedGestureToken.pointerSessionKey != pointerSessionKey -> "session_superseded"
                    expectedGestureToken.gestureGeneration != gestureGeneration -> "gesture_superseded"
                    else -> reason
                },
            maxDistance = maxDistance,
            touchSlop = touchSlop,
            pointerCount = pointerCount
        )
}

internal fun KuiklyThreadMessageItem.resolvedThreadAvatarWireValue(): String? {
    if (threadAuthorBadgeLabel() != null) return null
    // Avatar slot styling consumes the already-normalized Thread projection. It must not infer a
    // human author from unknown presentation data or from the legacy agent-id heuristic.
    val authorMemberKind = authorKind.projectedMemberKindOrNull() ?: return null
    val resolution = resolveAvatarSlot(
        kind = authorMemberKind,
        id = authorId.ifBlank { authorName },
        avatarWireValue = avatarWireValue
    )
    return resolution.effectiveAvatarWireValue
}

private fun String.isLikelyThreadAgentId(): Boolean =
    startsWith("agent", ignoreCase = true) ||
        startsWith("ai-", ignoreCase = true) ||
        contains("_agent", ignoreCase = true) ||
        contains("-agent", ignoreCase = true)

@Composable
private fun ThreadMessageAuthorBadge(label: String) {
    Box(
        modifier =
            Modifier
                .heightIn(min = 18.dp)
                .background(SlockColor.EmptyStateGray)
                .border(SlockStroke.Default, SlockColor.BorderBlack.copy(alpha = 0.3f))
                .padding(horizontal = SlockSpacing.Xs, vertical = 2.dp),
        contentAlignment = Alignment.Center
    ) {
        Text(
            text = label,
            style =
                SlockType.Caption
                    .withSlockFontWeight(FontWeight.Bold)
                    .copy(fontSize = 10.sp, color = SlockColor.TextBlack.copy(alpha = 0.6f)),
            color = SlockColor.TextBlack.copy(alpha = 0.6f),
            maxLines = 1,
            overflow = TextOverflow.Ellipsis
        )
    }
}

internal fun KuiklyThreadMessageItem.threadAuthorBadgeLabel(): String? =
    when {
        isDeletedThreadAuthor() -> "DELETED"
        isRemovedThreadHuman() -> "REMOVED"
        else -> null
    }

internal fun KuiklyThreadMessageItem.canOpenThreadAuthorProfile(): Boolean =
    threadAuthorBadgeLabel() == null

internal fun KuiklyThreadMessageItem.canOpenThreadAuthorProfile(shareSelectionActive: Boolean): Boolean =
    !shareSelectionActive && canOpenThreadAuthorProfile()

internal fun resolveThreadAgentStatusIndicatorState(
    message: KuiklyThreadMessageItem,
    canonicalState: SlockAgentStatusIndicatorState?
): SlockAgentStatusIndicatorState? =
    canonicalState.takeIf { message.showsAgentStatusIndicator() }

internal fun KuiklyThreadMessageItem.threadMentionHandle(
    serverMembersState: SharedServerMembersState = SharedServerMembersState(),
    serverId: ServerId? = null
): String? {
    if (threadAuthorBadgeLabel() != null) return null
    val cleanAuthorId = authorId.trim().takeIf { it.isNotBlank() }
    return threadMentionHandleFromCanonicalStore(
        serverMembersState.threadMentionAuthorHandle(serverId, cleanAuthorId)
    )
}

internal fun KuiklyThreadMessageItem.threadMentionHandle(
    serverMembersEntry: SharedServerMembersEntry,
    serverId: ServerId? = null
): String? {
    if (threadAuthorBadgeLabel() != null) return null
    val cleanAuthorId = authorId.trim().takeIf { it.isNotBlank() }
    val rosterHandle =
        serverMembersEntry
            .takeIf { entry -> entry.serverId == serverId?.value?.trim() }
            ?.members
            ?.firstOrNull { member -> member.id.value.trim() == cleanAuthorId }
            ?.let { member -> member.handle.canonicalServerMembersMentionHandle(member.id.value) }
    return threadMentionHandleFromCanonicalStore(rosterHandle)
}

internal fun KuiklyThreadMessageItem.threadMentionHandle(canonicalMemberHandle: String?): String? =
    if (threadAuthorBadgeLabel() != null) {
        null
    } else {
        threadMentionHandleFromCanonicalStore(
            canonicalMemberHandle.canonicalServerMembersMentionHandle(authorId)
        )
    }

private fun KuiklyThreadMessageItem.threadMentionHandleFromCanonicalStore(canonicalHandle: String?): String? {
    canonicalHandle?.let { return it }
    val cleanAuthorId = authorId.trim().takeIf { it.isNotBlank() }
    val explicitAuthorHandle = authorHandle.threadMentionExplicitAuthorHandle(authorName, cleanAuthorId)
    if (explicitAuthorHandle != null) return explicitAuthorHandle
    return null
}

private fun SharedServerMembersState.threadMentionAuthorHandle(
    serverId: ServerId?,
    authorId: String?
): String? {
    val cleanAuthorId = authorId?.trim()?.takeIf { it.isNotBlank() } ?: return null
    val cleanServerId = serverId?.value?.trim()?.takeIf { it.isNotBlank() }
    val channelHandle =
        channelMemberSlices.values
            .asSequence()
            .filter { slice -> cleanServerId == null || slice.serverId?.trim() == cleanServerId }
            .flatMap { slice -> slice.members.asSequence() }
            .filter { member -> member.id.value.trim() == cleanAuthorId }
            .mapNotNull { member -> member.handle.canonicalServerMembersMentionHandle(member.id.value) }
            .firstOrNull()
    if (channelHandle != null) return channelHandle
    val entries =
        if (cleanServerId != null) {
            listOfNotNull(entriesByServerId[cleanServerId])
        } else {
            entriesByServerId.values.toList()
        }
    return entries
        .asSequence()
        .flatMap { entry -> entry.members.asSequence() }
        .filter { member -> member.id.value.trim() == cleanAuthorId }
        .mapNotNull { member -> member.handle.canonicalServerMembersMentionHandle(member.id.value) }
        .firstOrNull()
}

private fun String?.threadMentionHandleValue(): String? =
    this
        ?.trim()
        ?.removePrefix("@")
        ?.takeIf { it.isNotBlank() }

private fun String.threadMentionExplicitAuthorHandle(authorName: String, authorId: String?): String? {
    val handle = threadMentionHandleValue() ?: return null
    val presentationName = authorName.threadMentionHandleValue()
    if (presentationName != null && handle == presentationName) return null
    if (handle.any { it.isWhitespace() }) return null
    return handle.canonicalServerMembersMentionHandle(authorId)
}

private fun KuiklyThreadMessageItem.isDeletedThreadAuthor(): Boolean =
    !authorDeletedAt.isNullOrBlank() || senderMembershipStatus.equals("deleted", ignoreCase = true)

private fun KuiklyThreadMessageItem.isRemovedThreadHuman(): Boolean =
    !isThreadAgentAuthor() && senderMembershipStatus.equals("removed", ignoreCase = true)

private fun KuiklyThreadMessageItem.isThreadAgentAuthor(): Boolean =
    authorKind.equals("agent", ignoreCase = true) || authorId.isLikelyThreadAgentId()

internal fun shouldSuppressCompactThreadAuthor(
    previous: KuiklyThreadMessageItem?,
    next: KuiklyThreadMessageItem,
    localOffsetMinutes: Int
): Boolean =
    previous?.isCompactContinuationBefore(next, localOffsetMinutes) == true

internal fun threadDateDividerLabel(
    previous: KuiklyThreadMessageItem?,
    next: KuiklyThreadMessageItem,
    timeContext: SlockTimeContext
): String? {
    val localOffsetMinutes = timeContext.localOffsetMinutes
    val nextEpochDay = next.threadMessageLocalEpochDayOrNull(localOffsetMinutes) ?: return null
    val previousEpochDay = previous?.threadMessageLocalEpochDayOrNull(localOffsetMinutes)
    if (previousEpochDay == nextEpochDay) return null
    val todayEpochDay =
        timeContext.todayEpochDay
            ?: timeContext.nowEpochMillis?.let { threadLocalEpochDay(it, localOffsetMinutes) }
    return threadDateDividerLabel(nextEpochDay, todayEpochDay)
}

private fun KuiklyThreadMessageItem.isCompactContinuationBefore(
    next: KuiklyThreadMessageItem,
    localOffsetMinutes: Int
): Boolean {
    if (isSystemMessage() || next.isSystemMessage()) return false
    val identityKey = authorIdentityKey()
    if (identityKey.isBlank() || identityKey != next.authorIdentityKey()) return false

    val currentEpochMillis = parseThreadMessageEpochMillisOrNull(localOffsetMinutes)
    val nextEpochMillis = next.parseThreadMessageEpochMillisOrNull(localOffsetMinutes)
    if (currentEpochMillis == null || nextEpochMillis == null) return false

    val elapsedMillis = nextEpochMillis - currentEpochMillis
    if (elapsedMillis !in 0..ThreadCompactContinuationWindowMillis) return false

    return threadLocalEpochDay(currentEpochMillis, localOffsetMinutes) ==
        threadLocalEpochDay(nextEpochMillis, localOffsetMinutes)
}

private fun KuiklyThreadMessageItem.parseThreadMessageEpochMillisOrNull(localOffsetMinutes: Int): Long? =
    parseSlockTimestampEpochMillisOrNull(timestampLabel, localOffsetMinutes)

private fun KuiklyThreadMessageItem.threadMessageLocalEpochDayOrNull(localOffsetMinutes: Int): Long? =
    parseThreadMessageEpochMillisOrNull(localOffsetMinutes)?.let { threadLocalEpochDay(it, localOffsetMinutes) }

private fun KuiklyThreadMessageItem.authorIdentityKey(): String =
    authorId.takeIf { it.isNotBlank() }
        ?: authorHandle.takeIf { it.isNotBlank() }
        ?: authorName.takeIf { it.isNotBlank() }
        ?: ""

private fun threadLocalEpochDay(epochMillis: Long, localOffsetMinutes: Int): Long =
    threadFloorDiv(epochMillis + localOffsetMinutes.toLong() * ThreadMillisPerMinute, ThreadMillisPerDay)

private fun threadFloorDiv(value: Long, divisor: Long): Long {
    val quotient = value / divisor
    val remainder = value % divisor
    return if (remainder != 0L && ((remainder < 0) != (divisor < 0))) quotient - 1 else quotient
}

private fun threadFloorMod(value: Long, divisor: Long): Long =
    value - threadFloorDiv(value, divisor) * divisor

private fun threadDateDividerLabel(epochDay: Long, todayEpochDay: Long?): String =
    when {
        todayEpochDay != null && epochDay == todayEpochDay -> "TODAY"
        todayEpochDay != null && epochDay == todayEpochDay - 1L -> "YESTERDAY"
        else -> {
            val date = threadCivilDateFromEpochDay(epochDay)
            "${ThreadWeekdayNames[threadWeekdayIndex(epochDay)]}, ${ThreadMonthNames[date.month - 1]} ${date.day}"
        }
    }

private data class ThreadCivilDate(
    val year: Int,
    val month: Int,
    val day: Int
)

private fun threadCivilDateFromEpochDay(epochDay: Long): ThreadCivilDate {
    val zeroDay = epochDay + 719_468L
    val era = threadFloorDiv(zeroDay, 146_097L)
    val dayOfEra = zeroDay - era * 146_097L
    val yearOfEra =
        (dayOfEra - dayOfEra / 1_460L + dayOfEra / 36_524L - dayOfEra / 146_096L) / 365L
    val year = yearOfEra + era * 400L
    val dayOfYear = dayOfEra - (365L * yearOfEra + yearOfEra / 4L - yearOfEra / 100L)
    val monthPrime = (5L * dayOfYear + 2L) / 153L
    val day = dayOfYear - (153L * monthPrime + 2L) / 5L + 1L
    val month = monthPrime + if (monthPrime < 10L) 3L else -9L
    val adjustedYear = year + if (month <= 2L) 1L else 0L
    return ThreadCivilDate(adjustedYear.toInt(), month.toInt(), day.toInt())
}

private fun threadWeekdayIndex(epochDay: Long): Int =
    threadFloorMod(epochDay + 4L, 7L).toInt()

private val ThreadWeekdayNames =
    listOf("SUNDAY", "MONDAY", "TUESDAY", "WEDNESDAY", "THURSDAY", "FRIDAY", "SATURDAY")

private val ThreadMonthNames =
    listOf("JANUARY", "FEBRUARY", "MARCH", "APRIL", "MAY", "JUNE", "JULY", "AUGUST", "SEPTEMBER", "OCTOBER", "NOVEMBER", "DECEMBER")

private const val ThreadMillisPerMinute = 60_000L
private const val ThreadMillisPerDay = 86_400_000L
private const val ThreadCompactContinuationWindowMillis = 30L * ThreadMillisPerMinute

internal data class ThreadInlineReplyPresentation(
    val replies: List<build.raft.app.network.sync.ReplyPreview>,
    val replyCount: Int,
    val unreadCount: Int,
    val hasDraft: Boolean,
)

/**
 * Header label for the inline-replies surface: ALWAYS the authoritative total, never
 * total-minus-visible previews. The retired "View N earlier replies" branch subtracted the
 * visible rows, which read as if only the undisplayed remainder existed (Web #5486 / cindyz
 * ruling: always show `n replies`, n = total reply count).
 */
internal data class ThreadInlineReplyCountLabel(
    val kind: Kind,
    val count: Int,
) {
    enum class Kind { One, Many }
}

internal fun ThreadInlineReplyPresentation.countLabel(): ThreadInlineReplyCountLabel =
    if (replyCount == 1) {
        ThreadInlineReplyCountLabel(ThreadInlineReplyCountLabel.Kind.One, 1)
    } else {
        ThreadInlineReplyCountLabel(ThreadInlineReplyCountLabel.Kind.Many, replyCount)
    }

internal fun threadInlineReplyPresentation(
    model: ThreadRepliesReadModel?,
    replyMetadata: ThreadReplyMetadata,
    hasDraft: Boolean,
): ThreadInlineReplyPresentation? {
    if (replyMetadata.replyCount <= 0) return null
    val replies =
        model
            ?.replies
            .orEmpty()
            .filterNot { it.senderType.equals("system", ignoreCase = true) }
            .takeLast(build.raft.app.network.sync.InlineThreadReplyPreviewLimit)
    // PR #5157: geometry belongs to actual conversation rows. Total replyCount includes
    // system history only for the label and must never reserve an empty/system-only footprint.
    if (replies.isEmpty()) return null
    val authoritativeReplyCount = maxOf(replyMetadata.replyCount, model?.replyCount ?: 0)
    return ThreadInlineReplyPresentation(
        replies = replies,
        replyCount = authoritativeReplyCount,
        unreadCount = replyMetadata.unreadReplyCount.coerceAtLeast(0),
        hasDraft = hasDraft,
    )
}

internal fun threadInlineReplyPresentationForMessage(
    model: ThreadRepliesReadModel?,
    replyMetadata: ThreadReplyMetadata,
    hasDraft: Boolean,
    showReplyAction: Boolean,
): ThreadInlineReplyPresentation? =
    if (showReplyAction) {
        threadInlineReplyPresentation(model, replyMetadata, hasDraft)
    } else {
        null
    }


internal val LocalThreadInlineReplyTimestampReporter =
    compositionLocalOf<((String, Offset, IntSize) -> Unit)?> { null }


@Composable
private fun ThreadInlineRepliesSurface(
    presentation: ThreadInlineReplyPresentation,
    participantsById: Map<String, KuiklyThreadMemberItem>,
    memberAvatarResolver: SlockMemberAvatarResolver,
    onOpenThread: () -> Unit,
) {
    val replyRowHeight = threadInlineReplyRowHeightDp(LocalDensity.current.fontScale).dp
    val hoverInteractionSource = remember { MutableInteractionSource() }
    val isHovered by hoverInteractionSource.collectIsHoveredAsState()
    val countLabelSpec = presentation.countLabel()
    val countLabel =
        when (countLabelSpec.kind) {
            ThreadInlineReplyCountLabel.Kind.One ->
                stringResource(MR.strings.thread_inline_reply_count_one)
            ThreadInlineReplyCountLabel.Kind.Many ->
                stringResource(MR.strings.thread_inline_reply_count_many, countLabelSpec.count)
        }
    val unreadLabel =
        presentation.unreadCount.takeIf { it > 0 }?.let { count ->
            stringResource(MR.strings.thread_inline_new_replies, count)
        }
    val draftLabel = stringResource(MR.strings.thread_inline_draft)
    Column(
        modifier =
            Modifier
                .fillMaxWidth()
                .padding(top = 6.dp)
                .hoverable(hoverInteractionSource)
                .background(threadNeutralMessageSurfaceColor(emphasized = isHovered))
                .clickable(onClick = onOpenThread)
                .padding(horizontal = 10.dp, vertical = 8.dp),
        verticalArrangement = Arrangement.spacedBy(5.dp),
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Text(
                text = buildString {
                    append(countLabel)
                    unreadLabel?.let { append(" · ").append(it) }
                    if (presentation.hasDraft) append(" · ✎ ").append(draftLabel)
                    append(" ›")
                },
                modifier = Modifier.weight(1f),
                style =
                    SlockType.Caption
                        .copy(fontSize = 12.5.sp, lineHeight = 16.sp, color = SlockColor.TextBlack.copy(alpha = 0.58f))
                        .withSlockFontWeight(FontWeight.Bold),
                color = SlockColor.TextBlack.copy(alpha = 0.58f),
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
        }
        presentation.replies.forEach { reply ->
            key("inline-reply:${reply.messageId}") {
                ThreadInlineReplyRow(
                    reply = reply,
                    participant = participantsById[reply.senderId],
                    memberAvatarResolver = memberAvatarResolver,
                    rowHeight = replyRowHeight,
                )
            }
        }
    }
}

@Composable
private fun ThreadInlineReplyRow(
    reply: build.raft.app.network.sync.ReplyPreview,
    participant: KuiklyThreadMemberItem?,
    memberAvatarResolver: SlockMemberAvatarResolver,
    rowHeight: Dp,
) {
    val timestampPositionReporter = LocalThreadInlineReplyTimestampReporter.current
    val resolvedAvatar = rememberSlockMemberAvatarWireValue(memberAvatarResolver, reply.senderId)
    val displayName =
        reply.senderDisplayName?.trim()?.takeIf { it.isNotBlank() }
            ?: participant?.displayName?.trim()?.takeIf { it.isNotBlank() }
            ?: reply.senderName.trim().ifBlank { reply.senderId }
    val avatarWireValue =
        resolveThreadRowAvatarWireValue(resolvedAvatar)
    Row(
        modifier =
            Modifier
                .fillMaxWidth()
                .height(rowHeight),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(6.dp),
    ) {
        SlockAvatar(
            avatarWireValue = avatarWireValue,
            label = displayName.take(1).uppercase(),
            avatarSize = 20.dp,
            borderWidth = SlockStroke.Thin,
            cacheSubject =
                slockMemberAvatarCacheSubject(
                    participant?.kind?.parsedMemberKindOrNull(),
                    reply.senderId
                ),
        )
        Text(
            text = displayName,
            style =
                SlockType.Caption
                    .copy(
                        fontSize = 12.5.sp,
                        lineHeight = ThreadInlineReplyContentLineHeightSp.sp,
                        color = SlockColor.TextBlack.copy(alpha = 0.72f),
                    )
                    .withSlockFontWeight(FontWeight.Bold),
            color = SlockColor.TextBlack.copy(alpha = 0.72f),
            maxLines = 1,
        )
        Text(
            text = threadInlineReplyPreviewText(reply.content),
            modifier = Modifier.weight(1f),
            style =
                SlockType.Caption.copy(
                    fontSize = 12.5.sp,
                    lineHeight = ThreadInlineReplyContentLineHeightSp.sp,
                ),
            color = SlockColor.TextBlack.copy(alpha = 0.62f),
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
        )
        if (reply.createdAt.isNotBlank()) {
            SlockRelativeTimestampText(
                value = reply.createdAt,
                modifier =
                    if (timestampPositionReporter == null) {
                        Modifier
                    } else {
                        Modifier.onGloballyPositioned { coordinates ->
                            timestampPositionReporter(
                                reply.messageId,
                                coordinates.positionInRoot(),
                                coordinates.size,
                            )
                        }
                    },
                displayGroup = SlockTimestampDisplayGroup.Conversation,
                style = ThreadInlineReplyTimestampStyle,
                color = SlockColor.TextBlack.copy(alpha = 0.42f),
                maxLines = 1,
                toggleEnabled = false,
            )
        }
    }
}

internal fun threadInlineReplyPreviewText(content: String): String =
    content
        .lineSequence()
        .map { line -> line.trim() }
        .filter(String::isNotBlank)
        .joinToString(" ")

/**
 * Keeps the original 20dp row at the default scale while preserving its 4dp breathing room when
 * the user's font scale grows. Kuikly's linear SP conversion is `sp * fontScale` in DP space.
 */
internal fun threadInlineReplyRowHeightDp(fontScale: Float): Float {
    val resolvedFontScale = fontScale.coerceAtLeast(1f)
    return maxOf(
        ThreadInlineReplyRowMinHeightDp,
        ThreadInlineReplyContentLineHeightSp * resolvedFontScale + ThreadInlineReplyRowVerticalAllowanceDp,
    )
}

private const val ThreadInlineReplyContentLineHeightSp = 16f
private const val ThreadInlineReplyRowMinHeightDp = 20f
private const val ThreadInlineReplyRowVerticalAllowanceDp = 4f

internal val ThreadInlineReplyTimestampStyle =
    SlockType.Caption.copy(
        fontFamily = SlockMonoFamily,
        fontSize = 11.5.sp,
        lineHeight = 15.sp,
    )

@Composable
internal fun ThreadMessageFooterMeta(
    message: KuiklyThreadMessageItem,
    taskOpenEnabled: Boolean,
    taskStatusActionsEnabled: Boolean,
    resolvedTaskAssigneeName: String? = null,
    alignEnd: Boolean,
    onOpenTask: (String) -> Unit,
    onShowActions: (SlockPopoverAnchor) -> Unit,
    onOpenTaskStatusMenu: (SlockPopoverAnchor) -> Unit,
    showSavedBadge: Boolean = false,
    showReactionAddAction: Boolean = false,
    onToggleReaction: ((String) -> Unit)? = null,
    onShowReactionDetails: ((KuiklyThreadReactionItem, SlockPopoverAnchor) -> Unit)? = null
) {
    val pendingReactionVisuals = LocalThreadPendingReactionVisuals.current
    val hasTask = message.hasThreadTaskFooterMeta()
    val visibleReactions =
        threadVisibleReactionsWithPending(
            messageId = message.id,
            reactions = message.reactions,
            pendingVisuals = pendingReactionVisuals
        )
    val hasReactions = visibleReactions.isNotEmpty()
    val showReactionAddChip = showReactionAddAction && hasReactions
    if (!hasTask && !showSavedBadge && !hasReactions && !showReactionAddChip) return

    Row(
        modifier = Modifier.fillMaxWidth(),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement =
            if (alignEnd) Arrangement.spacedBy(6.dp, Alignment.End) else Arrangement.spacedBy(6.dp)
    ) {
        if (hasTask) {
            val label = threadMessageTaskMetaLabel(message, resolvedTaskAssigneeName) ?: "Task"
            val selectedStatus = message.taskStatus.threadTaskStatusOption()
            val taskChipClick: ((SlockPopoverAnchor) -> Unit)? =
                when {
                    taskStatusActionsEnabled -> onOpenTaskStatusMenu
                    taskOpenEnabled -> { _ -> message.taskId?.let(onOpenTask) }
                    else -> null
                }
            val taskClickIdentity =
                threadTaskStatusChipClickIdentity(
                    message = message,
                    selectedStatus = selectedStatus,
                    taskStatusActionsEnabled = taskStatusActionsEnabled,
                    taskOpenEnabled = taskOpenEnabled
                )
            SlockAnchoredMetaChip(
                label = label,
                iconName = selectedStatus.icon,
                iconSize = selectedStatus.iconSize,
                color = selectedStatus.color,
                modifier = Modifier.weight(1f, fill = false).widthIn(max = 260.dp),
                clickIdentity = taskClickIdentity,
                anchorOwnerIdentity = threadMessageMenuOwnerIdentity(message.id),
                onClick = taskChipClick
            )
        }
        if (showSavedBadge) {
            SlockAnchoredMetaChip(
                label = stringResource(MR.strings.thread_label_saved),
                iconName = SlockLucideIconName.Bookmark,
                iconSize = 11.dp,
                iconColorArgb = ThreadMessageSavedBadgeIconColorArgb,
                iconFillArgb = ThreadMessageSavedBadgeIconColorArgb,
                color = ThreadMessageSavedBadgeColor,
                modifier = Modifier.widthIn(max = 96.dp),
                pressFeedback = false,
                clickIdentity = "thread-saved:${message.id}",
                onClick = null
            )
        }
        if (hasReactions) {
            visibleReactions.forEach { reaction ->
                key("reaction:${message.id}:${reaction.emoji}") {
                    ThreadReactionChip(
                        reaction = reaction,
                        interactionIdentity = "thread_reaction:${message.id}:${reaction.emoji}",
                        onClick = onToggleReaction?.let { callback -> { callback(reaction.emoji) } },
                        onLongPress =
                            onShowReactionDetails?.let { callback ->
                                { anchor -> callback(reaction, anchor) }
                            }
                    )
                }
            }
        }
        if (showReactionAddChip) {
            ThreadReactionAddChip(messageId = message.id, onClick = onShowActions)
        }
    }
}

internal data class ThreadReactionPendingKey(
    val messageId: String,
    val emoji: String
)

internal fun threadReactionPendingKey(messageId: String, emoji: String): ThreadReactionPendingKey =
    ThreadReactionPendingKey(messageId = messageId, emoji = emoji)

internal data class ThreadReactionPendingVisual(
    val reaction: KuiklyThreadReactionItem,
    val originalIndex: Int
)

internal fun List<KuiklyThreadReactionItem>.toPendingReactionVisual(
    emoji: String,
    selected: Boolean
): ThreadReactionPendingVisual {
    val originalIndex = indexOfFirst { reaction -> reaction.emoji == emoji }
    val original = getOrNull(originalIndex)
    val optimistic =
        if (original == null) {
            KuiklyThreadReactionItem(
                emoji = emoji,
                count = if (selected) 1 else 0,
                selected = selected
            )
        } else {
            original.copy(
                count =
                    when {
                        selected && !original.selected -> original.count + 1
                        !selected && original.selected -> (original.count - 1).coerceAtLeast(0)
                        else -> original.count
                    },
                selected = selected
            )
        }
    return ThreadReactionPendingVisual(
        reaction = optimistic,
        originalIndex = originalIndex.takeIf { it >= 0 } ?: size
    )
}

internal fun threadVisibleReactionsWithPending(
    messageId: String,
    reactions: List<KuiklyThreadReactionItem>,
    pendingVisuals: Map<ThreadReactionPendingKey, ThreadReactionPendingVisual>
): List<KuiklyThreadReactionItem> {
    val visible = reactions.filter { reaction -> reaction.count > 0 }.toMutableList()
    pendingVisuals
        .filterKeys { key -> key.messageId == messageId }
        .toList()
        .sortedBy { (_, visual) -> visual.originalIndex }
        .forEach { (key, visual) ->
            val currentIndex = visible.indexOfFirst { reaction -> reaction.emoji == key.emoji }
            if (visual.reaction.count <= 0) {
                if (currentIndex >= 0) visible.removeAt(currentIndex)
            } else if (currentIndex >= 0) {
                visible[currentIndex] = visual.reaction
            } else {
                visible.add(visual.originalIndex.coerceIn(0, visible.size), visual.reaction)
            }
        }
    return visible
}

internal val LocalThreadPendingReactionVisuals =
    compositionLocalOf<Map<ThreadReactionPendingKey, ThreadReactionPendingVisual>> { emptyMap() }

internal fun KuiklyThreadMessageItem.hasThreadFooterMeta(
    showSavedBadge: Boolean = false,
    hasPendingReaction: Boolean = false
): Boolean =
    hasThreadTaskFooterMeta() ||
        showSavedBadge ||
        hasPendingReaction ||
        reactions.any { it.count > 0 }

internal enum class ThreadMessageTrailingSection {
    MetaChips,
    InlineReplies,
}

internal fun threadMessageTrailingSectionOrder(
    hasMetaChips: Boolean,
    hasInlineReplies: Boolean,
): List<ThreadMessageTrailingSection> =
    buildList {
        if (hasMetaChips) add(ThreadMessageTrailingSection.MetaChips)
        if (hasInlineReplies) add(ThreadMessageTrailingSection.InlineReplies)
    }

private fun KuiklyThreadMessageItem.hasThreadTaskFooterMeta(): Boolean =
    !taskId.isNullOrBlank() ||
        taskNumber != null ||
        !taskStatus.isNullOrBlank() ||
        !taskAssigneeName.isNullOrBlank()

internal fun threadMessageTaskMetaLabel(
    message: KuiklyThreadMessageItem,
    resolvedTaskAssigneeName: String? = null
): String? {
    val number = message.taskNumber?.let { "#$it" }
    val assignee =
        resolvedTaskAssigneeName
            ?.trim()
            ?.removePrefix("@")
            ?.takeIf { it.isNotBlank() }
    if (number == null && assignee == null && message.taskStatus.isNullOrBlank() && message.taskId.isNullOrBlank()) {
        return null
    }
    return buildString {
        append(number ?: "Task")
        assignee?.let {
            append(" @")
            append(it)
        }
    }
}

internal fun String.isDisplaySafeTaskAssigneeName(assigneeId: String? = null): Boolean {
    val trimmed = trim().removePrefix("@")
    if (trimmed.isBlank()) return false
    if (trimmed.isUuidLike()) return false
    val normalizedId = assigneeId?.trim()?.removePrefix("@")
    return normalizedId == null || !trimmed.equals(normalizedId, ignoreCase = true) || !normalizedId.isUuidLike()
}

private fun String.isUuidLike(): Boolean {
    val trimmed = trim()
    if (trimmed.length != 36) return false
    val dashPositions = setOf(8, 13, 18, 23)
    return trimmed.withIndex().all { (index, char) ->
        if (index in dashPositions) {
            char == '-'
        } else {
            char in '0'..'9' || char in 'a'..'f' || char in 'A'..'F'
        }
    }
}

internal fun Set<SharedThreadComposerDraftRecord>.toReplyComposerDraftParentMessageIds(): Set<String> =
    mapNotNull { record ->
        record.parentMessageId?.takeIf { !record.isRootComposer && it.isNotBlank() }
