@Composable
private fun ThreadMessageAvatarSlot(
    interactionIdentity: String,
    showAvatar: Boolean,
    showTimestamp: Boolean,
    compactTimestampGutter: Boolean,
    timestampLabel: String,
    timestampAlignment: Alignment,
    timestampTextAlign: TextAlign,
    avatarLabel: String,
    avatarWireValue: String?,
    avatarDiagnostics: SlockAvatarRowDiagnostics? = null,
    cacheSubject: build.raft.app.data.SlockAvatarCacheSubject? = null,
    status: SlockAgentStatusIndicatorState?,
    statusPulsing: () -> Boolean = { true },
    muted: Boolean = false,
    external: Boolean = false,
    onClick: () -> Unit,
    onLongPress: () -> Unit = {}
) {
    val slotLayout = threadMessageMetadataSlotLayout(showAvatar, compactTimestampGutter, showTimestamp)
    Box(
        modifier = Modifier.width(slotLayout.widthDp.dp).height(slotLayout.heightDp.dp),
        contentAlignment = timestampAlignment
    ) {
        when {
            showAvatar ->
                // React parity: MessageSenderAvatar carries mt-0.5 (2px) so the
                // avatar top optically aligns with the name glyphs.
                Box(modifier = Modifier.padding(top = 2.dp)) {
                    ThreadMessageAvatar(
                        interactionIdentity = interactionIdentity,
                        avatarLabel = avatarLabel,
                        avatarWireValue = avatarWireValue,
                        avatarDiagnostics = avatarDiagnostics,
                        cacheSubject = cacheSubject,
                        status = status,
                        statusPulsing = statusPulsing,
                        muted = muted,
                        external = external,
                        onClick = onClick,
                        onLongPress = onLongPress
                    )
                }
            slotLayout.timestampVisible ->
                Text(
                    text = timestampLabel,
                    style =
                        SlockType.Caption.copy(
                            fontFamily = SlockMonoFamily,
                            fontSize = 11.sp,
                            lineHeight = 14.sp,
                            color = SlockColor.TextBlack.copy(alpha = 0.38f)
                        ),
                    color = SlockColor.TextBlack.copy(alpha = 0.38f),
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    textAlign = timestampTextAlign,
                    modifier =
                        Modifier
                            .width(slotLayout.widthDp.dp)
                            .align(timestampAlignment)
                )
        }
    }
}

@Composable
private fun ThreadMessageAvatar(
    interactionIdentity: String,
    avatarLabel: String,
    avatarWireValue: String?,
    avatarDiagnostics: SlockAvatarRowDiagnostics? = null,
    cacheSubject: build.raft.app.data.SlockAvatarCacheSubject? = null,
    status: SlockAgentStatusIndicatorState?,
    statusPulsing: () -> Boolean = { true },
    muted: Boolean = false,
    external: Boolean = false,
    onClick: () -> Unit,
    onLongPress: () -> Unit = {}
) {
    val gestureOwner =
        rememberSlockGestureOwner(
            surface = "thread-message-avatar",
            semanticIdentity = interactionIdentity,
            callbacks = ThreadMessageAvatarGestureCallbacks(onClick, onLongPress)
        )
    val avatarSource =
        remember(avatarWireValue) {
            avatarWireValue?.takeIf { it.isNotBlank() }
        }
    Box(
        modifier =
            Modifier
                .size(36.dp)
                .slockGesturePointerInput(gestureOwner) { owner ->
                    var gesture: SlockGestureSession<ThreadMessageAvatarGestureCallbacks>? = null
                    detectTapGestures(
                        onPress = {
                            gesture = owner.beginGesture()
                            tryAwaitRelease()
                        },
                        onTap = {
                            (gesture ?: owner.beginGesture()).currentCallbacksOrNull()?.onClick()
                        },
                        onLongPress = {
                            (gesture ?: owner.beginGesture()).currentCallbacksOrNull()?.onLongPress()
                        }
                    )
                },
        contentAlignment = Alignment.Center
    ) {
        SlockAvatarWithStatus(
            statusColor = if (muted) null else status?.color,
            avatarSize = 36.dp,
            // #90 React parity: bump chat thread avatar overlay status dot
            // 10dp → 11dp to match React `StatusDot size="lg"` (size-[11px]).
            statusSize = 11.dp,
            statusPulsing = status?.pulsing == true && statusPulsing()
        ) {
            Box(modifier = Modifier.fillMaxSize()) {
                if (external && avatarSource == null) {
                    ThreadExternalAuthorAvatarFallback(muted = muted)
                } else {
                SlockAvatar(
                    avatarWireValue = avatarSource,
                    label = avatarLabel,
                    diagnostics = avatarDiagnostics,
                    modifier = if (muted) Modifier.alpha(0.62f) else Modifier,
                    avatarSize = 36.dp,
                    borderWidth = SlockStroke.Default,
                    cacheSubject = cacheSubject
                )
                }
                if (muted) {
                    Box(
                        modifier =
                            Modifier
                                .fillMaxSize()
                                .background(SlockColor.EmptyStateGray.copy(alpha = 0.38f))
                    )
                }
            }
        }
    }
}

